INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3012507, 423478, 53316, '<td valign="top">Wow, for some reason this photo just really appeals to me. I think the faces are interesting, and they point my attention towards the food while allowing me to focus on them also (the elements don''t distract from each other, is I guess what I am saying).</td>', 'Wow, for some reason this photo just really appeals to me. I think the faces are interesting, and they point my attention towards the food while allowing me to focus on them also (the elements don''t distract from each other, is I guess what I am saying).', '2006-11-08 01:28:16.000000', NULL, 1),
(3012553, 422037, 66201, '<td valign="top">The reflection is a tad muted...Would have opted to leave out the newspaper reflection (use as an overlay in an advanced editing challnege perhaps). I know I had this problem too trying to get a brighter reflection. Lovely concept for a portrait though:)</td>', 'The reflection is a tad muted...Would have opted to leave out the newspaper reflection (use as an overlay in an advanced editing challnege perhaps). I know I had this problem too trying to get a brighter reflection. Lovely concept for a portrait though:)', '2006-11-08 01:36:10.000000', NULL, 1),
(3012558, 421847, 67698, '<td valign="top">No cutting remarks here. This is a very unusual shot! Love the backliting and the silhouette effect. You definitely made the chop. Congrats!<br/> <br/>Ok, I''m done with the puns (a double-edged blade, they be). Stay sharp :P</td>', 'No cutting remarks here. This is a very unusual shot! Love the backliting and the silhouette effect. You definitely made the chop. Congrats! Ok, I''m done with the puns (a double-edged blade, they be). Stay sharp :P', '2006-11-08 01:37:09.000000', NULL, 1),
(3012564, 423913, 66201, '<td valign="top">perhaps a tighter crop to make the leaf more of a subject...? Interesting effect happening on the water .</td>', 'perhaps a tighter crop to make the leaf more of a subject...? Interesting effect happening on the water .', '2006-11-08 01:38:27.000000', NULL, 1),
(3012565, 421366, 67698, '<td valign="top">While its a nice reflection, the image feels a stop or so underexposed, or at least the levels could use some adjustment.</td>', 'While its a nice reflection, the image feels a stop or so underexposed, or at least the levels could use some adjustment.', '2006-11-08 01:38:57.000000', NULL, 1),
(3012571, 424149, 67698, '<td valign="top">Nice angle, and very clean reflection. Almost like its meant to be there. Nice.</td>', 'Nice angle, and very clean reflection. Almost like its meant to be there. Nice.', '2006-11-08 01:39:31.000000', NULL, 1),
(3012572, 422974, 66201, '<td valign="top">were we allowed to clone in this challenge? Very architectural shot though.</td>', 'were we allowed to clone in this challenge? Very architectural shot though.', '2006-11-08 01:39:54.000000', NULL, 1),
(3012576, 423116, 66201, '<td valign="top">I see you and I see your camera!!!  Like the colours and vibe of the background</td>', 'I see you and I see your camera!!!  Like the colours and vibe of the background', '2006-11-08 01:40:55.000000', NULL, 1),
(3012579, 424216, 67698, '<td valign="top">Nice evening shot, and great shiny reflections, but the image feels quite oversharpened.</td>', 'Nice evening shot, and great shiny reflections, but the image feels quite oversharpened.', '2006-11-08 01:41:22.000000', NULL, 1),
(3012580, 421967, 66201, '<td valign="top">very intriguing image</td>', 'very intriguing image', '2006-11-08 01:41:22.000000', NULL, 1),
(3012582, 424442, 66201, '<td valign="top">that''s great.</td>', 'that''s great.', '2006-11-08 01:41:59.000000', NULL, 1),
(3012589, 423907, 67698, '<td valign="top">Very neat shot. Interesting perspective! Love the shadows at the bottom of the water.</td>', 'Very neat shot. Interesting perspective! Love the shadows at the bottom of the water.', '2006-11-08 01:42:55.000000', NULL, 1),
(3012590, 424369, 66201, '<td valign="top">tighter crop would have been nice...great image</td>', 'tighter crop would have been nice...great image', '2006-11-08 01:43:05.000000', NULL, 1),
(3012592, 423468, 67698, '<td valign="top">Gorgeous colors. I actually had to do a double-take and figure out what it was I''m looking it - the reflection is just so clear!</td>', 'Gorgeous colors. I actually had to do a double-take and figure out what it was I''m looking it - the reflection is just so clear!', '2006-11-08 01:44:08.000000', NULL, 1),
(3012596, 421286, 67698, '<td valign="top">Lovely capture of a dynamic moment. Simple and elegant.</td>', 'Lovely capture of a dynamic moment. Simple and elegant.', '2006-11-08 01:44:38.000000', NULL, 1),
(3012597, 422786, 66201, '<td valign="top">This is so interesting. I would have preferred a head-on shot to get the parallels of the windows working. I love the way some windows are  within the reflected sky.</td>', 'This is so interesting. I would have preferred a head-on shot to get the parallels of the windows working. I love the way some windows are  within the reflected sky.', '2006-11-08 01:44:54.000000', NULL, 1),
(3012602, 424038, 67698, '<td valign="top">Beautiful sunset colors! Great shot</td>', 'Beautiful sunset colors! Great shot', '2006-11-08 01:45:57.000000', NULL, 1),
(3012605, 423485, 66201, '<td valign="top">well done...a difficult shot</td>', 'well done...a difficult shot', '2006-11-08 01:46:25.000000', NULL, 1),
(3012611, 423912, 21816, '<td valign="top">Awesome work.</td>', 'Awesome work.', '2006-11-08 01:47:26.000000', NULL, 1),
(3012617, 424336, 67698, '<td valign="top">I really like this composition - it really works. However, something about the lighting feels off - it looks like flash was used, or at least it looks like there is a source of light right in front of her.</td>', 'I really like this composition - it really works. However, something about the lighting feels off - it looks like flash was used, or at least it looks like there is a source of light right in front of her.', '2006-11-08 01:48:52.000000', NULL, 1),
(3012623, 423993, 67698, '<td valign="top">Lovely colors and composition. Very cool lighting effects. Congrats!</td>', 'Lovely colors and composition. Very cool lighting effects. Congrats!', '2006-11-08 01:50:51.000000', NULL, 1),
(3012624, 424270, 67324, '<td valign="top">Yum, coffee.</td>', 'Yum, coffee.', '2006-11-08 01:50:55.000000', NULL, 1),
(3012631, 422991, 67698, '<td valign="top">Wish the image was less blurry. Otherwise, nice guitar.</td>', 'Wish the image was less blurry. Otherwise, nice guitar.', '2006-11-08 01:52:53.000000', NULL, 1),
(3012639, 423069, 67698, '<td valign="top">Great composition. Love the colors and vast sky. Beautiful.</td>', 'Great composition. Love the colors and vast sky. Beautiful.', '2006-11-08 01:55:02.000000', NULL, 1),
(3012642, 421401, 21816, '<td valign="top">You need to add some more contrast to give it more body!</td>', 'You need to add some more contrast to give it more body!', '2006-11-08 01:55:18.000000', NULL, 1),
(3012654, 424210, 67698, '<td valign="top">Ghostly fog back there! I like the hazy feel of this picture. Its creepy, in a good way!</td>', 'Ghostly fog back there! I like the hazy feel of this picture. Its creepy, in a good way!', '2006-11-08 01:59:00.000000', NULL, 1),
(3012657, 424400, 67698, '<td valign="top">Love the lights of the city. I do wish the image was a bit more contrasty. The levels need some adjustment, methinks.</td>', 'Love the lights of the city. I do wish the image was a bit more contrasty. The levels need some adjustment, methinks.', '2006-11-08 02:00:06.000000', NULL, 1),
