(3012766, 423232, 67258, '<td valign="top">A beautiful photograph.</td>', 'A beautiful photograph.', '2006-11-08 02:56:16.000000', NULL, 1),
(3012768, 424067, 45475, '<td valign="top">Yeah, that hits the spot. Bottoms up! :)</td>', 'Yeah, that hits the spot. Bottoms up! :)', '2006-11-08 02:57:01.000000', NULL, 1),
(3012786, 423720, 66398, '<td valign="top">Wow this is cool in so many ways... I love that the beaks touch, the tail touches and the legs touch but the feet are on the belly too.</td>', 'Wow this is cool in so many ways... I love that the beaks touch, the tail touches and the legs touch but the feet are on the belly too.', '2006-11-08 03:02:44.000000', NULL, 1),
(3012817, 423251, 67258, '<td valign="top">A lovely photograph, but it will lose a couple of marks from me as part of the challenge was to ''creatively'' capture reflections.</td>', 'A lovely photograph, but it will lose a couple of marks from me as part of the challenge was to ''creatively'' capture reflections.', '2006-11-08 03:35:43.000000', NULL, 1),
(3012844, 423806, 21816, '<td valign="top">Clever!</td>', 'Clever!', '2006-11-08 03:55:38.000000', NULL, 1),
(3012849, 424288, 48389, '<td valign="top">WOW! Man do I wish I as there right now, Valley View Turnout?!! What lovely fall colours, nice light on El Capitan and cool reflections. Your one lucky person!! :o)</td>', 'WOW! Man do I wish I as there right now, Valley View Turnout?!! What lovely fall colours, nice light on El Capitan and cool reflections. Your one lucky person!! :o)', '2006-11-08 03:58:33.000000', NULL, 1),
(3012902, 422790, 65886, '<td valign="top">so very poetic and beautiful!</td>', 'so very poetic and beautiful!', '2006-11-08 04:44:43.000000', NULL, 1),
