(3013180, 422552, 67705, '<td valign="top">Reminds me of a Van Gogh</td>', 'Reminds me of a Van Gogh', '2006-11-08 07:24:49.000000', NULL, 1),
(3013183, 423811, 67258, '<td valign="top">Very early! Certainly you meet the criteria of <i><b>creatively</b></i> photograph a reflecting surface, but I do wonder if you could perhaps lift this image with a boost to levels?</td>', 'Very early! Certainly you meet the criteria of creatively photograph a reflecting surface, but I do wonder if you could perhaps lift this image with a boost to levels?', '2006-11-08 07:25:52.000000', NULL, 1),
(3013189, 424427, 60987, '<td valign="top">reflection is lost in the movement of the water. the big black strip down the right is distracting also.</td>', 'reflection is lost in the movement of the water. the big black strip down the right is distracting also.', '2006-11-08 07:27:49.000000', NULL, 1),
