(3013197, 421363, 67258, '<td valign="top">Not keen on the colour caste, but the ghostly reflection is certainly effective.</td>', 'Not keen on the colour caste, but the ghostly reflection is certainly effective.', '2006-11-08 07:30:26.000000', NULL, 1),
