(3014614, 424280, 40106, '<td valign="top">i love puddles :D 7</td>', 'i love puddles :D 7', '2006-11-08 13:45:29.000000', NULL, 1),
(3014622, 422986, 66201, '<td valign="top">I''m guessing this is a bit of tree/drift wood on a pond/lake. It has great image value, but because you''ve not contextualised it, it''s become abstract. I also struggle to find a focus here. I don''t think your title helps you...it gets the viewer stuck on the "evil" which is not necessarily there.</td>', 'I''m guessing this is a bit of tree/drift wood on a pond/lake. It has great image value, but because you''ve not contextualised it, it''s become abstract. I also struggle to find a focus here. I don''t think your title helps you...it gets the viewer stuck on the "evil" which is not necessarily there.', '2006-11-08 13:47:12.000000', NULL, 1),
(3014633, 424167, 66201, '<td valign="top">Aaah...an evening with Joanie: now that would be worth a million reflections!!! Sorry..got swept away by the thought of sitting in on a concert of hers: okay now I''m looking at your picture. Interesting overlays.</td>', 'Aaah...an evening with Joanie: now that would be worth a million reflections!!! Sorry..got swept away by the thought of sitting in on a concert of hers: okay now I''m looking at your picture. Interesting overlays.', '2006-11-08 13:49:51.000000', NULL, 1),
