(3015406, 423025, 66515, '<td valign="top">From the challenge description: Creatively photograph a reflecting surface <b>that is not a mirror </b>while keeping your camera out of the shot<br/> <br/>Sorry. DNMC</td>', 'From the challenge description: Creatively photograph a reflecting surface that is not a mirror while keeping your camera out of the shot Sorry. DNMC', '2006-11-08 17:02:24.000000', NULL, 1),
(3015409, 423116, 66515, '<td valign="top">"Creatively photograph a reflecting surface that is not a mirror <b>while keeping your camera out of the shot</b>"<br/> <br/> <br/>Sorry...DNMC</td>', '"Creatively photograph a reflecting surface that is not a mirror while keeping your camera out of the shot"  Sorry...DNMC', '2006-11-08 17:04:04.000000', NULL, 1),
(3015414, 423388, 14045, '<td valign="top">you weren''t suposta be in the picture.</td>', 'you weren''t suposta be in the picture.', '2006-11-08 17:05:46.000000', NULL, 1),
(3015421, 423485, 14045, '<td valign="top">nice...10</td>', 'nice...10', '2006-11-08 17:08:14.000000', NULL, 1),
(3015442, 424343, 40718, '<td valign="top">there seems to be some mild halos around the trees in the reflection.  I''m guessing it''s a large radius USM?  To even out the reflection and real sky, use a graduated ND filter.  the reflection color is nice, the blow sky? no so much. 5</td>', 'there seems to be some mild halos around the trees in the reflection.  I''m guessing it''s a large radius USM?  To even out the reflection and real sky, use a graduated ND filter.  the reflection color is nice, the blow sky? no so much. 5', '2006-11-08 17:13:20.000000', NULL, 1),
(3015450, 424442, 14045, '<td valign="top">nice 10</td>', 'nice 10', '2006-11-08 17:14:42.000000', NULL, 1),
