INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3017644, 424023, 22734, '<td valign="top">Impressive! 7</td>', 'Impressive! 7', '2006-11-09 13:08:35.000000', NULL, 1),
(3017661, 423562, 60298, '<td valign="top">Wow! what a nicely composed shot.  Excellent use of the puddle.</td>', 'Wow! what a nicely composed shot.  Excellent use of the puddle.', '2006-11-09 13:15:23.000000', NULL, 1),
(3017708, 424330, 66201, '<td valign="top">There is a brooding, sombre feeling in this. I don''t personally like the green hue saturation. Interesting composition though.</td>', 'There is a brooding, sombre feeling in this. I don''t personally like the green hue saturation. Interesting composition though.', '2006-11-09 13:33:50.000000', NULL, 1),
(3017710, 424419, 66201, '<td valign="top">very witty take on the theme.</td>', 'very witty take on the theme.', '2006-11-09 13:34:30.000000', NULL, 1),
(3017717, 423112, 66201, '<td valign="top">Lovely: has the look of a watercolour painting. Very geometric in a way, but soft.</td>', 'Lovely: has the look of a watercolour painting. Very geometric in a way, but soft.', '2006-11-09 13:36:55.000000', NULL, 1),
(3017725, 423533, 66201, '<td valign="top">okay...recognise those sign boards: such a breath of fresh air after all those autumnal northern hemisphere landscapes :). Good Luck!!</td>', 'okay...recognise those sign boards: such a breath of fresh air after all those autumnal northern hemisphere landscapes :). Good Luck!!', '2006-11-09 13:41:54.000000', NULL, 1),
(3017729, 424216, 66201, '<td valign="top">This has so much atmosphere: If the hooded figure were in focus I would have given this a 9. I see that the street has focus, but because the eye is drawn to that particular figure, it needs to be in focus.</td>', 'This has so much atmosphere: If the hooded figure were in focus I would have given this a 9. I see that the street has focus, but because the eye is drawn to that particular figure, it needs to be in focus.', '2006-11-09 13:43:51.000000', NULL, 1),
(3017735, 424146, 67006, '<td valign="top">Doesn''t seem to meet the challenge, but I love it anyway!  Interesting...</td>', 'Doesn''t seem to meet the challenge, but I love it anyway!  Interesting...', '2006-11-09 13:46:43.000000', NULL, 1),
(3017739, 423257, 56846, '<td valign="top">Wonderful shot, but the reflection is a bit weak because of the ripples.</td>', 'Wonderful shot, but the reflection is a bit weak because of the ripples.', '2006-11-09 13:47:32.000000', NULL, 1),
(3017740, 424178, 56846, '<td valign="top">Creative setup.  Not too interesting overall though...</td>', 'Creative setup.  Not too interesting overall though...', '2006-11-09 13:48:27.000000', NULL, 1),
