(3017782, 424265, 2382, '<td valign="top">Is this a reflection?  it looks like two different people to me.</td>', 'Is this a reflection?  it looks like two different people to me.', '2006-11-09 14:01:12.000000', NULL, 1),
(3017794, 422790, 66201, '<td valign="top">I love the way the leaves are reflected "inside" the sphere. Magical reflections inside and outside ... Beautiful!!</td>', 'I love the way the leaves are reflected "inside" the sphere. Magical reflections inside and outside ... Beautiful!!', '2006-11-09 14:08:17.000000', NULL, 1),
(3017797, 423133, 56846, '<td valign="top">Good composition...Focus seems like it could be sharper.</td>', 'Good composition...Focus seems like it could be sharper.', '2006-11-09 14:09:22.000000', NULL, 1),
(3017798, 423557, 67258, '<td valign="top">That really is a true moment of serendipity - glad you were there to catch it! I am scoring 7 - mainly for the composition and for ''seeing'' the photograph.  The exposure is slightly out, causing the brightest whites to be blown, but that said, swans are notoriously dificult to expose properly, especially as on top of the different shades of white there is also the problem of light reflecting off the water.  I would also prefer to see just a little more space around the swans and their reflections - as it they seem just a little too tightly boxed in.</td>', 'That really is a true moment of serendipity - glad you were there to catch it! I am scoring 7 - mainly for the composition and for ''seeing'' the photograph.  The exposure is slightly out, causing the brightest whites to be blown, but that said, swans are notoriously dificult to expose properly, especially as on top of the different shades of white there is also the problem of light reflecting off the water.  I would also prefer to see just a little more space around the swans and their reflections - as it they seem just a little too tightly boxed in.', '2006-11-09 14:09:43.000000', NULL, 1),
(3017799, 424073, 2382, '<td valign="top">simple cliche but beautiful.</td>', 'simple cliche but beautiful.', '2006-11-09 14:09:44.000000', NULL, 1),
(3017802, 423252, 2382, '<td valign="top">beautiful shot... i love the colors!</td>', 'beautiful shot... i love the colors!', '2006-11-09 14:11:12.000000', NULL, 1),
(3017803, 424433, 67006, '<td valign="top">Cool pic.  Reflected onto fabric?  Do tell more, please!</td>', 'Cool pic.  Reflected onto fabric?  Do tell more, please!', '2006-11-09 14:11:17.000000', NULL, 1),
(3017821, 422105, 2382, '<td valign="top">beautiful relection.  I would have tried to position somewhere without the foreground.  It seems to distract (IMO).</td>', 'beautiful relection.  I would have tried to position somewhere without the foreground.  It seems to distract (IMO).', '2006-11-09 14:17:59.000000', NULL, 1),
