(3021022, 424270, 66599, '<td valign="top">This photo should be the winner!  I think the toaster reflection was a great idea that fits the spirit of this challenge.</td>', 'This photo should be the winner!  I think the toaster reflection was a great idea that fits the spirit of this challenge.', '2006-11-10 21:05:40.000000', NULL, 1),
(3021026, 424467, 66599, '<td valign="top">This is a good shot that really fits the spirit of the challenge.  Good job.</td>', 'This is a good shot that really fits the spirit of the challenge.  Good job.', '2006-11-10 21:07:30.000000', NULL, 1),
(3021048, 424247, 66599, '<td valign="top">This is such a great shot.  The reflection is so sharp and clear.  Good work.</td>', 'This is such a great shot.  The reflection is so sharp and clear.  Good work.', '2006-11-10 21:20:34.000000', NULL, 1),
