(3022504, 422782, 65603, '<td valign="top">I think this is very nicely done, nice add with the water ripple.</td>', 'I think this is very nicely done, nice add with the water ripple.', '2006-11-11 20:35:14.000000', NULL, 1),
(3022505, 423744, 30982, '<td valign="top">I have no idea why I like this, but I like this.  It''s oddly charming in a weird sorta way.</td>', 'I have no idea why I like this, but I like this.  It''s oddly charming in a weird sorta way.', '2006-11-11 20:35:26.000000', NULL, 1),
