(3027287, 421280, 57229, '<td valign="top">Nice. A painting. 7</td>', 'Nice. A painting. 7', '2006-11-13 15:04:00.000000', NULL, 1),
(3027293, 424351, 57229, '<td valign="top">And if you look down below the castle - right down there under the roadway and the trees and the river wall and the lights - you can see some little reflections. Geddit? No. 5</td>', 'And if you look down below the castle - right down there under the roadway and the trees and the river wall and the lights - you can see some little reflections. Geddit? No. 5', '2006-11-13 15:05:32.000000', NULL, 1),
(3027299, 424036, 57229, '<td valign="top">These pictures are very hard to get right, but your title is brilliant. It strikes me as being the sort of picture that the challenge is all about, so you''ll get either 7 or 8 for being a cheeky monkey. (and I don''t like to reveal too much)</td>', 'These pictures are very hard to get right, but your title is brilliant. It strikes me as being the sort of picture that the challenge is all about, so you''ll get either 7 or 8 for being a cheeky monkey. (and I don''t like to reveal too much)', '2006-11-13 15:08:03.000000', NULL, 1),
(3027300, 424360, 57229, '<td valign="top">Damn. A wholely clichéd up reflection-of-trees-in-water type entry and you nevertheless made the reflection the major element. Validated, yet! Take 7</td>', 'Damn. A wholely clichéd up reflection-of-trees-in-water type entry and you nevertheless made the reflection the major element. Validated, yet! Take 7', '2006-11-13 15:09:50.000000', NULL, 1),
(3027304, 424491, 57229, '<td valign="top">I sense an impenetrable veneer of misfortune :) Good shot. 7</td>', 'I sense an impenetrable veneer of misfortune :) Good shot. 7', '2006-11-13 15:10:59.000000', NULL, 1),
(3027322, 424181, 57229, '<td valign="top">Excellent. Not a tree or river in sight. How do you do that? I know, you were concerned about the electronics.<br/>Seriously - great shot that could be used with text about the content. Meets the challenge head-on and flattens it 7?, nah 8. All right then 9</td>', 'Excellent. Not a tree or river in sight. How do you do that? I know, you were concerned about the electronics.Seriously - great shot that could be used with text about the content. Meets the challenge head-on and flattens it 7?, nah 8. All right then 9', '2006-11-13 15:14:42.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3027326, 424468, 57229, '<td valign="top">There''s an opus in this (contrast of the glossy model picture to the unglossy modeling experience) which you don''t get over so very directly. Yer good enough for a 7 though.</td>', 'There''s an opus in this (contrast of the glossy model picture to the unglossy modeling experience) which you don''t get over so very directly. Yer good enough for a 7 though.', '2006-11-13 15:16:13.000000', NULL, 1),
