(3027335, 422644, 57229, '<td valign="top">Most excellent duck shot, but there''s still more duck than reflection, pictorially. 6</td>', 'Most excellent duck shot, but there''s still more duck than reflection, pictorially. 6', '2006-11-13 15:18:00.000000', NULL, 1),
(3027341, 423440, 57229, '<td valign="top">It must seem rude, but my impression is of a gratuitous binty shot with a token reflection to sneak in to the challenge.</td>', 'It must seem rude, but my impression is of a gratuitous binty shot with a token reflection to sneak in to the challenge.', '2006-11-13 15:19:44.000000', NULL, 1),
(3027344, 423257, 57229, '<td valign="top">Another great shot, but the reflections are incidental.</td>', 'Another great shot, but the reflections are incidental.', '2006-11-13 15:20:43.000000', NULL, 1),
(3027349, 424149, 57229, '<td valign="top">Good. You managed to give reflection precedence over the reflected. (Apparently that''s not easy). 7</td>', 'Good. You managed to give reflection precedence over the reflected. (Apparently that''s not easy). 7', '2006-11-13 15:22:08.000000', NULL, 1),
