(3029005, 423252, 68504, '<td valign="top">Intriguing, lovely, but the upper non reflected background detracts.</td>', 'Intriguing, lovely, but the upper non reflected background detracts.', '2006-11-14 00:43:44.000000', NULL, 1),
(3029006, 421925, 65498, '<td valign="top">nice idea.. I would have preferred a longer DOF for the foreground in focus too..</td>', 'nice idea.. I would have preferred a longer DOF for the foreground in focus too..', '2006-11-14 00:45:01.000000', NULL, 1),
