(3029011, 424087, 68504, '<td valign="top">Wonderful the way the piano disappears via its relection into the windows, but the blown highlights on the piano bench detract.</td>', 'Wonderful the way the piano disappears via its relection into the windows, but the blown highlights on the piano bench detract.', '2006-11-14 00:47:55.000000', NULL, 1),
(3029015, 424451, 68504, '<td valign="top">Stunning definition and contrast, but a little too monochromatic for me.</td>', 'Stunning definition and contrast, but a little too monochromatic for me.', '2006-11-14 00:49:04.000000', NULL, 1),
