(3029735, 424481, 42100, '<td valign="top">Very rich and vibrant color tones in this beautiful scene.  The composition feels kind of unbalanced and is probably the weak point of this photo.</td>', 'Very rich and vibrant color tones in this beautiful scene.  The composition feels kind of unbalanced and is probably the weak point of this photo.', '2006-11-14 09:47:09.000000', NULL, 1),
(3029741, 423088, 42100, '<td valign="top">Beautiful reflection, it''s every bit as rich and vibrant as the real.  Nicely done!</td>', 'Beautiful reflection, it''s every bit as rich and vibrant as the real.  Nicely done!', '2006-11-14 09:49:08.000000', NULL, 1),
(3029750, 423838, 42100, '<td valign="top">Which planet in the universe did you travel to, to take this photo.  Totally unreal color, beautiful!</td>', 'Which planet in the universe did you travel to, to take this photo.  Totally unreal color, beautiful!', '2006-11-14 09:51:06.000000', NULL, 1),
(3029768, 421367, 42100, '<td valign="top">Excellent color and contrast, along with great sky reflection.  A very unconventional composition, feels a little chopped off, or a little tight.  I''m not saying it''s bad or anything, it''s just so unique it''s takes a little more thought.</td>', 'Excellent color and contrast, along with great sky reflection.  A very unconventional composition, feels a little chopped off, or a little tight.  I''m not saying it''s bad or anything, it''s just so unique it''s takes a little more thought.', '2006-11-14 09:56:43.000000', NULL, 1),
(3029810, 423912, 42100, '<td valign="top">Great reflection in this calm and relaxing scene.  Well done!</td>', 'Great reflection in this calm and relaxing scene.  Well done!', '2006-11-14 10:08:24.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3029826, 423252, 42100, '<td valign="top">Very unique and unusual photo for the challenge.  Great composition and choice of DOF.  Well done!</td>', 'Very unique and unusual photo for the challenge.  Great composition and choice of DOF.  Well done!', '2006-11-14 10:12:02.000000', NULL, 1),
(3029847, 424325, 50695, '<td valign="top">There seems to be a movement afoot at DPC to create painterly images with motion blur. The results are spectacular. I''m all for it. 10</td>', 'There seems to be a movement afoot at DPC to create painterly images with motion blur. The results are spectacular. I''m all for it. 10', '2006-11-14 10:17:20.000000', NULL, 1),
(3029851, 423598, 50695, '<td valign="top">Gorgeous. I''ll start this at 9. perfect coordination of subject and background. bump to 10</td>', 'Gorgeous. I''ll start this at 9. perfect coordination of subject and background. bump to 10', '2006-11-14 10:18:23.000000', NULL, 1),
(3029871, 421847, 68100, '<td valign="top">I love the idea, from a distance I thought it was a meditating pose, quite the opposite. For me the meditating pose would have suited the lighting and colour wonderfully,</td>', 'I love the idea, from a distance I thought it was a meditating pose, quite the opposite. For me the meditating pose would have suited the lighting and colour wonderfully,', '2006-11-14 10:21:52.000000', NULL, 1),
(3029888, 423035, 68100, '<td valign="top">I love how abstract this image is and the use of black &amp; white with that stunning green. nice one.</td>', 'I love how abstract this image is and the use of black & white with that stunning green. nice one.', '2006-11-14 10:24:14.000000', NULL, 1),
(3029909, 422089, 68100, '<td valign="top">I like the idea, but it would have been lovely to see the whole of the bird at the top of the image.</td>', 'I like the idea, but it would have been lovely to see the whole of the bird at the top of the image.', '2006-11-14 10:27:28.000000', NULL, 1),
(3029924, 421286, 50695, '<td valign="top">one sees a cycle between the legs and their reflection, as if they are going into their reflection and coming back out again, over and over again. It adds energy to the shot. All art, all photography, all poetry requires a leap. Notice that this leap has failed. The starting foot has hit the water and the leading foot is about to hit the water. It is by failing our leap that we immerse ourselves. 8 bump to 9</td>', 'one sees a cycle between the legs and their reflection, as if they are going into their reflection and coming back out again, over and over again. It adds energy to the shot. All art, all photography, all poetry requires a leap. Notice that this leap has failed. The starting foot has hit the water and the leading foot is about to hit the water. It is by failing our leap that we immerse ourselves. 8 bump to 9', '2006-11-14 10:29:40.000000', NULL, 1),
(3029925, 422474, 50695, '<td valign="top">broken shapes of straightness conflict with round shapes and fuzz shapes. We realize that some of those straight shapes are themselves round, just part of a very large circle. It is a pleasing visual cacophony that seems to organize itself the more you look at it, but once you look away it falls back into a glorious mess. 8 bump to 9</td>', 'broken shapes of straightness conflict with round shapes and fuzz shapes. We realize that some of those straight shapes are themselves round, just part of a very large circle. It is a pleasing visual cacophony that seems to organize itself the more you look at it, but once you look away it falls back into a glorious mess. 8 bump to 9', '2006-11-14 10:29:46.000000', NULL, 1),
(3029927, 424244, 50695, '<td valign="top">How did you get a fall leaf to reflect green? Fantastic. And that large green shape on top completes composition. You have 3 main S curves reflecting each other, and a smaller S curve, also reflected. The S curve is a beautiful line. You can''t lose! 8 bump to 9</td>', 'How did you get a fall leaf to reflect green? Fantastic. And that large green shape on top completes composition. You have 3 main S curves reflecting each other, and a smaller S curve, also reflected. The S curve is a beautiful line. You can''t lose! 8 bump to 9', '2006-11-14 10:29:52.000000', NULL, 1),
(3029928, 421925, 50695, '<td valign="top">Narcissus drowns the viewer in a photograph. 9</td>', 'Narcissus drowns the viewer in a photograph. 9', '2006-11-14 10:29:55.000000', NULL, 1),
(3029930, 422986, 50695, '<td valign="top">Great illusion, great texture. 9</td>', 'Great illusion, great texture. 9', '2006-11-14 10:29:59.000000', NULL, 1),
(3029931, 424453, 50695, '<td valign="top">there is a mirroring of texture as well as the actual reflection. 8</td>', 'there is a mirroring of texture as well as the actual reflection. 8', '2006-11-14 10:30:05.000000', NULL, 1),
(3029934, 424437, 50695, '<td valign="top">excellent fulfillment of the challenge. good angle, great distortions. I''ll start this at 8.</td>', 'excellent fulfillment of the challenge. good angle, great distortions. I''ll start this at 8.', '2006-11-14 10:30:20.000000', NULL, 1),
(3029935, 424095, 50695, '<td valign="top">beautiful texture. 8</td>', 'beautiful texture. 8', '2006-11-14 10:30:27.000000', NULL, 1),
(3029938, 424120, 50695, '<td valign="top">I sort of see a shark, but I just love the bold abstract composition with a hand sticking into it. 8</td>', 'I sort of see a shark, but I just love the bold abstract composition with a hand sticking into it. 8', '2006-11-14 10:30:56.000000', NULL, 1),
(3029945, 421275, 50695, '<td valign="top">enigmatic but grim. I could easily imagine this as an image of remorse. With that title, the cylinder looks like a spent shotgun shell. 8</td>', 'enigmatic but grim. I could easily imagine this as an image of remorse. With that title, the cylinder looks like a spent shotgun shell. 8', '2006-11-14 10:32:25.000000', NULL, 1),
(3029949, 423744, 50695, '<td valign="top">herb street, her best... the letters are provocative. I like this mysterious image that suggests the interior, small-made-large world of the introvert. 8</td>', 'herb street, her best... the letters are provocative. I like this mysterious image that suggests the interior, small-made-large world of the introvert. 8', '2006-11-14 10:34:08.000000', NULL, 1),
(3029951, 422935, 50695, '<td valign="top">I like the small real woman completely dominated and subsumed (consumed?) by the advertising image. 8</td>', 'I like the small real woman completely dominated and subsumed (consumed?) by the advertising image. 8', '2006-11-14 10:34:48.000000', NULL, 1),
(3029957, 423582, 50695, '<td valign="top">There are lots of shots like this, but yours is the best, with those scary wires cutting across it and that flame-like flash towards the bottom. 8</td>', 'There are lots of shots like this, but yours is the best, with those scary wires cutting across it and that flame-like flash towards the bottom. 8', '2006-11-14 10:35:42.000000', NULL, 1),
(3029961, 424265, 50695, '<td valign="top">You gotta love that blank creepy horror-movie stare that fits the grainy processing perfectly. Utterly cinematic, and I''m talking about a really good movie. 9</td>', 'You gotta love that blank creepy horror-movie stare that fits the grainy processing perfectly. Utterly cinematic, and I''m talking about a really good movie. 9', '2006-11-14 10:36:40.000000', NULL, 1),
(3029964, 424383, 50695, '<td valign="top">amazing ripple effect. How''d you do that? 8</td>', 'amazing ripple effect. How''d you do that? 8', '2006-11-14 10:36:58.000000', NULL, 1),
(3029968, 424146, 50695, '<td valign="top">Bad title. You have not failed. You should have title it "writer''s block". There''s nothing more annoying that a self-deprecating brilliant person. Shame on you! ;) 9</td>', 'Bad title. You have not failed. You should have title it "writer''s block". There''s nothing more annoying that a self-deprecating brilliant person. Shame on you! ;) 9', '2006-11-14 10:38:45.000000', NULL, 1),
(3029970, 423025, 50695, '<td valign="top">let''s see, you put a mirror in the shot and your non-mirror reflections are tiny and subtle. You get my "non-DPC 7".</td>', 'let''s see, you put a mirror in the shot and your non-mirror reflections are tiny and subtle. You get my "non-DPC 7".', '2006-11-14 10:39:18.000000', NULL, 1),
(3029981, 422622, 50695, '<td valign="top">good creepy effect. 7</td>', 'good creepy effect. 7', '2006-11-14 10:42:18.000000', NULL, 1),
(3029982, 424280, 50695, '<td valign="top">this has a certain empty serenity that I like. 7</td>', 'this has a certain empty serenity that I like. 7', '2006-11-14 10:42:26.000000', NULL, 1),
(3029983, 423520, 50695, '<td valign="top">I like the minimalism of this, and the darkness contributes to a somber, suspenseful mood. 8</td>', 'I like the minimalism of this, and the darkness contributes to a somber, suspenseful mood. 8', '2006-11-14 10:43:03.000000', NULL, 1),
(3029986, 423502, 50695, '<td valign="top">I think I want even more of the bank cropped out. It''s hard to know until you see it, but right now the presence of the bank keeps reminding me this is upside-down, upsetting the dream effect. Or maybe you could process it so the bank blends in with its reflection better. That might be a job for an advanced challenge. I''ll give you a 7 for creativity.</td>', 'I think I want even more of the bank cropped out. It''s hard to know until you see it, but right now the presence of the bank keeps reminding me this is upside-down, upsetting the dream effect. Or maybe you could process it so the bank blends in with its reflection better. That might be a job for an advanced challenge. I''ll give you a 7 for creativity.', '2006-11-14 10:43:19.000000', NULL, 1),
(3029988, 423354, 50695, '<td valign="top">An implied story makes for a compelling photo. 7</td>', 'An implied story makes for a compelling photo. 7', '2006-11-14 10:43:51.000000', NULL, 1),
(3029990, 424419, 50695, '<td valign="top">Ha! You are a man of few words. You get my "LOL 7"</td>', 'Ha! You are a man of few words. You get my "LOL 7"', '2006-11-14 10:44:01.000000', NULL, 1),
(3029992, 423201, 50695, '<td valign="top">great title! starting this at 7. this is like a mix between Chagall and Mondrian. bump to 8</td>', 'great title! starting this at 7. this is like a mix between Chagall and Mondrian. bump to 8', '2006-11-14 10:44:34.000000', NULL, 1),
(3029995, 423913, 50695, '<td valign="top">Great composition. I''m not sure if the leaf highlights want to be so bright. 7</td>', 'Great composition. I''m not sure if the leaf highlights want to be so bright. 7', '2006-11-14 10:45:43.000000', NULL, 1),
(3029999, 423208, 50695, '<td valign="top">A good eye for composition, and the good idea of including the building with its reflection, makes this one of the best building in a building shots. 8</td>', 'A good eye for composition, and the good idea of including the building with its reflection, makes this one of the best building in a building shots. 8', '2006-11-14 10:46:50.000000', NULL, 1),
(3030007, 422534, 50695, '<td valign="top">fascinating composition, and the reflection becomes a symbol for how religion can affect all aspects of life, in unexpected and intimate ways. 8</td>', 'fascinating composition, and the reflection becomes a symbol for how religion can affect all aspects of life, in unexpected and intimate ways. 8', '2006-11-14 10:47:58.000000', NULL, 1),
(3030011, 423533, 50695, '<td valign="top">I love the way the sign interacts with the building and I love the framing redness. 7</td>', 'I love the way the sign interacts with the building and I love the framing redness. 7', '2006-11-14 10:48:52.000000', NULL, 1),
(3030013, 424247, 50695, '<td valign="top">A stunning image, but I want a more dynamic or interesting composition. 7</td>', 'A stunning image, but I want a more dynamic or interesting composition. 7', '2006-11-14 10:49:48.000000', NULL, 1),
(3030015, 423809, 50695, '<td valign="top">Cars (made after the 60s) are so boring to me, but this is a good composition and the colors are good. 7</td>', 'Cars (made after the 60s) are so boring to me, but this is a good composition and the colors are good. 7', '2006-11-14 10:50:43.000000', NULL, 1),
(3030018, 424094, 50695, '<td valign="top">is that a real window? if it is, let me know and I''ll give you a 10. 7</td>', 'is that a real window? if it is, let me know and I''ll give you a 10. 7', '2006-11-14 10:51:02.000000', NULL, 1),
(3030026, 424391, 50695, '<td valign="top">your title leads me to imagine that this is an abandoned prison, and the people walking by are a family whose elder generations and ancestors were sometimes imprisoned there, probably unfairly. They walk casually past it, but all have a secret terror of it, even in its ghostly state. 7</td>', 'your title leads me to imagine that this is an abandoned prison, and the people walking by are a family whose elder generations and ancestors were sometimes imprisoned there, probably unfairly. They walk casually past it, but all have a secret terror of it, even in its ghostly state. 7', '2006-11-14 10:53:01.000000', NULL, 1),
(3030029, 424401, 50695, '<td valign="top">nice of those sticks to line up for you like that. I just have never been able to get along with sticks. It is essential to the picture that you captured the highlights of the sticks on the left, which would otherwise be lost in shadow. Those highlights complete the line along the bottom. 7</td>', 'nice of those sticks to line up for you like that. I just have never been able to get along with sticks. It is essential to the picture that you captured the highlights of the sticks on the left, which would otherwise be lost in shadow. Those highlights complete the line along the bottom. 7', '2006-11-14 10:55:14.000000', NULL, 1),
(3030032, 421280, 50695, '<td valign="top">Painterly, Terry-Gilliamesque. 7</td>', 'Painterly, Terry-Gilliamesque. 7', '2006-11-14 10:55:56.000000', NULL, 1),
(3030034, 421847, 50695, '<td valign="top">Impressive, and a great reflection up top. We always think that water reflects, but if you''re underwater then air reflects! I predicted two ribbon-winners so far. Is this the third? 8</td>', 'Impressive, and a great reflection up top. We always think that water reflects, but if you''re underwater then air reflects! I predicted two ribbon-winners so far. Is this the third? 8', '2006-11-14 10:57:20.000000', NULL, 1),
(3030038, 424128, 50695, '<td valign="top">Simply beautiful. You have a painter''s eye. 8</td>', 'Simply beautiful. You have a painter''s eye. 8', '2006-11-14 10:58:08.000000', NULL, 1),
(3030039, 424419, 67001, '<td valign="top">hahaha! Very daring attempt at "reflections"... I have to give you a nice 8 for creativity.</td>', 'hahaha! Very daring attempt at "reflections"... I have to give you a nice 8 for creativity.', '2006-11-14 10:58:19.000000', NULL, 1),
(3030040, 423562, 50695, '<td valign="top">I''m afraid that this is becoming a cliche, but you executed it very well. 7</td>', 'I''m afraid that this is becoming a cliche, but you executed it very well. 7', '2006-11-14 10:58:53.000000', NULL, 1),
(3030042, 423810, 50695, '<td valign="top">good composition, bold crop. 7</td>', 'good composition, bold crop. 7', '2006-11-14 10:59:17.000000', NULL, 1),
(3030049, 424408, 50695, '<td valign="top">fragmentation is always an interesting technique in photography. Fragmentation of an artist/performer is rich with figurative meanings. Separating the mind from the hands is particularly rich. I wonder if this would have been stronger if the hands were frozen instead of motion blurred... 7</td>', 'fragmentation is always an interesting technique in photography. Fragmentation of an artist/performer is rich with figurative meanings. Separating the mind from the hands is particularly rich. I wonder if this would have been stronger if the hands were frozen instead of motion blurred... 7', '2006-11-14 11:01:21.000000', NULL, 1),
(3030055, 424226, 50695, '<td valign="top">fascinating to see the goose isolated not in emptiness but in a swirling chaos of color that includes his own reflection. 8</td>', 'fascinating to see the goose isolated not in emptiness but in a swirling chaos of color that includes his own reflection. 8', '2006-11-14 11:02:22.000000', NULL, 1),
(3030056, 422778, 50695, '<td valign="top">I suppose the sharp tacks have already told you that this isn''t a reflection. It''s a really cool photo, though. 7</td>', 'I suppose the sharp tacks have already told you that this isn''t a reflection. It''s a really cool photo, though. 7', '2006-11-14 11:02:27.000000', NULL, 1),
(3030061, 422518, 50695, '<td valign="top">Jackson Pollocky. 8</td>', 'Jackson Pollocky. 8', '2006-11-14 11:02:57.000000', NULL, 1),
(3030064, 423806, 50695, '<td valign="top">amazing capture and creative twist of the challenge. It''s not DNMC, it''s OOB! 8</td>', 'amazing capture and creative twist of the challenge. It''s not DNMC, it''s OOB! 8', '2006-11-14 11:03:56.000000', NULL, 1),
(3030068, 424467, 50695, '<td valign="top">The spoon looks like an eye. This is a striking, emotional photograph reminiscent of the Surrealist movement. 9</td>', 'The spoon looks like an eye. This is a striking, emotional photograph reminiscent of the Surrealist movement. 9', '2006-11-14 11:04:51.000000', NULL, 1),
(3030075, 424017, 50695, '<td valign="top">I think this would have been more effective if you hadn''t thrown in the kitchen sink. 7</td>', 'I think this would have been more effective if you hadn''t thrown in the kitchen sink. 7', '2006-11-14 11:06:20.000000', NULL, 1),
(3030078, 421366, 50695, '<td valign="top">Great texture. 7</td>', 'Great texture. 7', '2006-11-14 11:06:45.000000', NULL, 1),
(3030083, 424036, 50695, '<td valign="top">a remarkably rewarding abstract composition of bright color.  8</td>', 'a remarkably rewarding abstract composition of bright color.  8', '2006-11-14 11:07:48.000000', NULL, 1),
(3030088, 421560, 50695, '<td valign="top">I find it fascinating to see such an iconic image fragmented. This is the second entry where an icon is reflected on a residential window. It suggests how large abstract things affect us on an intimate level. 8</td>', 'I find it fascinating to see such an iconic image fragmented. This is the second entry where an icon is reflected on a residential window. It suggests how large abstract things affect us on an intimate level. 8', '2006-11-14 11:09:55.000000', NULL, 1),
(3030094, 424300, 50695, '<td valign="top">turning this upside down emphasizes the stiff verticality of the legs, which makes for an energetic composition. 7</td>', 'turning this upside down emphasizes the stiff verticality of the legs, which makes for an energetic composition. 7', '2006-11-14 11:10:55.000000', NULL, 1),
(3030097, 423210, 50695, '<td valign="top">What I like about this is that the only way we can see the spoon is via its reflections. 7</td>', 'What I like about this is that the only way we can see the spoon is via its reflections. 7', '2006-11-14 11:11:42.000000', NULL, 1),
(3030102, 421363, 50695, '<td valign="top">B&amp;w is a great choice that sets you apart from other duck and goose shots. This has a dignity to it, a sense of "portrait." 7</td>', 'B&w is a great choice that sets you apart from other duck and goose shots. This has a dignity to it, a sense of "portrait." 7', '2006-11-14 11:12:33.000000', NULL, 1),
(3030105, 421391, 50695, '<td valign="top">iconic image. 7</td>', 'iconic image. 7', '2006-11-14 11:13:05.000000', NULL, 1),
(3030108, 424286, 50695, '<td valign="top">I love the cinnamon color and the relentlessly repeating pattern of windows. 7</td>', 'I love the cinnamon color and the relentlessly repeating pattern of windows. 7', '2006-11-14 11:13:30.000000', NULL, 1),
(3030112, 424339, 50695, '<td valign="top">great face distortion, appropriate to subject. Composition is just ok. 7</td>', 'great face distortion, appropriate to subject. Composition is just ok. 7', '2006-11-14 11:14:11.000000', NULL, 1),
(3030115, 424490, 50695, '<td valign="top">beautiful wet feel to the reflection. such sensuous steel! 8</td>', 'beautiful wet feel to the reflection. such sensuous steel! 8', '2006-11-14 11:14:49.000000', NULL, 1),
(3030119, 424281, 50695, '<td valign="top">good composition. the "overexposure" is essential to simplifying the composition. 7</td>', 'good composition. the "overexposure" is essential to simplifying the composition. 7', '2006-11-14 11:16:00.000000', NULL, 1),
(3030125, 422989, 50695, '<td valign="top">I like the yellows and reds, and the fanciful but comfortable corner being reflected. I feel like I''m in a Parisian cafe, even though (especially though) I''ve never been to Paris. 7</td>', 'I like the yellows and reds, and the fanciful but comfortable corner being reflected. I feel like I''m in a Parisian cafe, even though (especially though) I''ve never been to Paris. 7', '2006-11-14 11:17:47.000000', NULL, 1),
(3030132, 422400, 50695, '<td valign="top">puddle, chainlink fence, dirt/gravel/asphalt, cattails... these are a few of my favorite things! 7</td>', 'puddle, chainlink fence, dirt/gravel/asphalt, cattails... these are a few of my favorite things! 7', '2006-11-14 11:19:25.000000', NULL, 1),
(3030133, 424216, 50695, '<td valign="top">gorgeous processing. I''d love to hear how you did this. 8</td>', 'gorgeous processing. I''d love to hear how you did this. 8', '2006-11-14 11:19:39.000000', NULL, 1),
(3030135, 424271, 50695, '<td valign="top">finally, a guitar picture with some Picasso flair! 8</td>', 'finally, a guitar picture with some Picasso flair! 8', '2006-11-14 11:19:50.000000', NULL, 1),
(3030140, 424092, 50695, '<td valign="top">Heartwarming but with an exciting, slightly disorienting, in-your-face composition. 8</td>', 'Heartwarming but with an exciting, slightly disorienting, in-your-face composition. 8', '2006-11-14 11:21:02.000000', NULL, 1),
(3030144, 422089, 50695, '<td valign="top">Postmodern flamingo of the Queen of Hearts. 8</td>', 'Postmodern flamingo of the Queen of Hearts. 8', '2006-11-14 11:22:12.000000', NULL, 1),
(3030146, 423904, 50695, '<td valign="top">not a pleasant photo to look at, per se, but an excellent fulfillment of the challenge, 7.</td>', 'not a pleasant photo to look at, per se, but an excellent fulfillment of the challenge, 7.', '2006-11-14 11:22:42.000000', NULL, 1),
(3030151, 423031, 50695, '<td valign="top">cliche, but a strong diagonal composition and a perfectly executed and processed shot with a great reflection in the eye. 7</td>', 'cliche, but a strong diagonal composition and a perfectly executed and processed shot with a great reflection in the eye. 7', '2006-11-14 11:23:40.000000', NULL, 1),
(3030155, 421420, 50695, '<td valign="top">Cliched, but just the right amount of exposure on the eye and the skin around the eye to reveal just enough detail. 7</td>', 'Cliched, but just the right amount of exposure on the eye and the skin around the eye to reveal just enough detail. 7', '2006-11-14 11:24:40.000000', NULL, 1),
(3030161, 423293, 50695, '<td valign="top">powerful, phallic composition. I like how everything is in focus and everything has details from dark to light, except for one "blown" highlight that helps to emphasize your subject. 8</td>', 'powerful, phallic composition. I like how everything is in focus and everything has details from dark to light, except for one "blown" highlight that helps to emphasize your subject. 8', '2006-11-14 11:26:00.000000', NULL, 1),
(3030162, 423252, 50695, '<td valign="top">7 for the bokeh.</td>', '7 for the bokeh.', '2006-11-14 11:26:06.000000', NULL, 1),
(3030168, 421279, 50695, '<td valign="top">gloriously disorienting (and noisy!) 8</td>', 'gloriously disorienting (and noisy!) 8', '2006-11-14 11:26:48.000000', NULL, 1),
(3030172, 424001, 50695, '<td valign="top">This is not an entirely original idea, but I''ve never seen it on DPC before and it is well executed. In fact, I''ve only seen it in video, not a still. It works well as a still, though I''m sure it''s harder to pull off that way. 8</td>', 'This is not an entirely original idea, but I''ve never seen it on DPC before and it is well executed. In fact, I''ve only seen it in video, not a still. It works well as a still, though I''m sure it''s harder to pull off that way. 8', '2006-11-14 11:28:23.000000', NULL, 1),
(3030175, 422463, 50695, '<td valign="top">Extra points for overexposing the highlights to create a field of negative space. 7</td>', 'Extra points for overexposing the highlights to create a field of negative space. 7', '2006-11-14 11:29:11.000000', NULL, 1),
(3030179, 422590, 50695, '<td valign="top">Hopperesque, a moving portrait of isolation with a perfect title. 9 bump to 10</td>', 'Hopperesque, a moving portrait of isolation with a perfect title. 9 bump to 10', '2006-11-14 11:30:08.000000', NULL, 1),
(3030180, 424023, 50695, '<td valign="top">Great capture and a really beautiful composition. 9 bump to 10</td>', 'Great capture and a really beautiful composition. 9 bump to 10', '2006-11-14 11:30:15.000000', NULL, 1),
(3030182, 423485, 50695, '<td valign="top">I predict a ribbon for this. 9 bump to 10</td>', 'I predict a ribbon for this. 9 bump to 10', '2006-11-14 11:30:56.000000', NULL, 1),
