(3032088, 423505, 66000, '<td valign="top">Very well executed, the reflection seems almost as an afterthought... I did not notice it until I consciously made the effort - the blub is so prominent.</td>', 'Very well executed, the reflection seems almost as an afterthought... I did not notice it until I consciously made the effort - the blub is so prominent.', '2006-11-14 22:55:35.000000', NULL, 1),
(3032090, 424173, 66000, '<td valign="top">Simply wow.</td>', 'Simply wow.', '2006-11-14 22:56:20.000000', NULL, 1),
(3032092, 421498, 66000, '<td valign="top">Gorgous, bright, and simple...  I love it.</td>', 'Gorgous, bright, and simple...  I love it.', '2006-11-14 22:57:02.000000', NULL, 1),
(3032095, 421847, 64462, '<td valign="top">how is this done?!</td>', 'how is this done?!', '2006-11-14 22:58:16.000000', NULL, 1),
(3032098, 424226, 66000, '<td valign="top">I really enjoy the intensity of colour in this photo.  With the entirety of the water covered in reflection, the duck seems to be swimming in a liquid forest.  It''s almost unreal.</td>', 'I really enjoy the intensity of colour in this photo.  With the entirety of the water covered in reflection, the duck seems to be swimming in a liquid forest.  It''s almost unreal.', '2006-11-14 22:58:35.000000', NULL, 1),
(3032107, 423719, 66000, '<td valign="top">I really like the linear style of this photo.  The sky is so free reflected in the water, but it''s so rigid at the same time because of the fields bordering it.  Well done!</td>', 'I really like the linear style of this photo.  The sky is so free reflected in the water, but it''s so rigid at the same time because of the fields bordering it.  Well done!', '2006-11-14 23:00:12.000000', NULL, 1),
(3032123, 424206, 64462, '<td valign="top">can''t help feeling like werewolf!</td>', 'can''t help feeling like werewolf!', '2006-11-14 23:02:23.000000', NULL, 1),
(3032127, 422518, 64462, '<td valign="top">amazing colours!</td>', 'amazing colours!', '2006-11-14 23:03:34.000000', NULL, 1),
(3032150, 424407, 64462, '<td valign="top">looks a bit red oversaturated on piles. but great picture</td>', 'looks a bit red oversaturated on piles. but great picture', '2006-11-14 23:08:23.000000', NULL, 1),
(3032158, 423723, 64462, '<td valign="top">horizon is not level. and blurring is arguable IMO, though it might be an intention...</td>', 'horizon is not level. and blurring is arguable IMO, though it might be an intention...', '2006-11-14 23:09:50.000000', NULL, 1),
(3032189, 424419, 21816, '<td valign="top">Hehe...a great take on the subject. Some interesting notes there?? ;)</td>', 'Hehe...a great take on the subject. Some interesting notes there?? ;)', '2006-11-14 23:17:21.000000', NULL, 1),
(3032197, 423232, 21816, '<td valign="top">This is a beautiful shot! Best of luck!</td>', 'This is a beautiful shot! Best of luck!', '2006-11-14 23:19:07.000000', NULL, 1),
(3032250, 424101, 61755, '<td valign="top">Nice! I like the stark contrast between the white and the blue - it adds to the reflection in the pond.</td>', 'Nice! I like the stark contrast between the white and the blue - it adds to the reflection in the pond.', '2006-11-14 23:34:27.000000', NULL, 1),
(3032258, 424173, 61755, '<td valign="top">Wow - now that''s a very clear reflection in a lake.  Nice job.</td>', 'Wow - now that''s a very clear reflection in a lake.  Nice job.', '2006-11-14 23:35:20.000000', NULL, 1),
(3032263, 424202, 61755, '<td valign="top">Fits well with the challenge theme and it is something a bit different from the usual landscape-based reflection photos.</td>', 'Fits well with the challenge theme and it is something a bit different from the usual landscape-based reflection photos.', '2006-11-14 23:37:04.000000', NULL, 1),
