INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3034492, 423232, 5728, '<td valign="top">Good one terje!</td>', 'Good one terje!', '2006-11-15 13:38:29.000000', NULL, 0),
(3034502, 424442, 41746, '<td valign="top">Superb shot - should have been higher IMO. Pure beauty. I love the flower in her eyes and you have executed this perfectly.</td>', 'Superb shot - should have been higher IMO. Pure beauty. I love the flower in her eyes and you have executed this perfectly.', '2006-11-15 13:40:26.000000', NULL, 0),
(3034510, 423606, 50695, '<td valign="top">Wow. I love Sylvia Plath, but did not know that poem. Your photo is such an excellent image to go with it. If I''d known that I would have given you an 11! ;)</td>', 'Wow. I love Sylvia Plath, but did not know that poem. Your photo is such an excellent image to go with it. If I''d known that I would have given you an 11! ;)', '2006-11-15 13:41:51.000000', NULL, 0),
(3034523, 424442, 52549, '<td valign="top">Wow! What a superb shot. Congrats on your top 20 finish.</td>', 'Wow! What a superb shot. Congrats on your top 20 finish.', '2006-11-15 13:45:23.000000', NULL, 0),
(3034720, 424429, 14476, '<td valign="top">Very nice, Jeff.  I like the "light on white" effect and the smoothness of the design.</td>', 'Very nice, Jeff.  I like the "light on white" effect and the smoothness of the design.', '2006-11-15 14:55:04.000000', NULL, 0),
(3034728, 423598, 3032, '<td valign="top">I didn''t vote on this challenge, let''s start with that.<br/>I really like this photo, the contradiction of the cold vs the summer clothes, the freshness of the pose/dance, the beautiful background and the balance of the blue and red/orange tints. the composition is quite good.<br/> <br/>The reason why it didn''t score higher is probably because you, dancing around on that snow, are the main subject here. You draw all the attention. The background, with the reflection, becomes the secondary subject. For this picture this is a great background, but challengewise the background is not the main focal point, not the in your face subject and therefore the whole photo gets rated lower.<br/>Personally, I really don''t like the border. The bleu tone of it is so bright that it pulss the eye out of the frame. Use a darker tone of blue or just black or no border at all.<br/> <br/>I''d give it a 6 in this challenge, otherwise it would be a 7+</td>', 'I didn''t vote on this challenge, let''s start with that.I really like this photo, the contradiction of the cold vs the summer clothes, the freshness of the pose/dance, the beautiful background and the balance of the blue and red/orange tints. the composition is quite good. The reason why it didn''t score higher is probably because you, dancing around on that snow, are the main subject here. You draw all the attention. The background, with the reflection, becomes the secondary subject. For this picture this is a great background, but challengewise the background is not the main focal point, not the in your face subject and therefore the whole photo gets rated lower.Personally, I really don''t like the border. The bleu tone of it is so bright that it pulss the eye out of the frame. Use a darker tone of blue or just black or no border at all. I''d give it a 6 in this challenge, otherwise it would be a 7+', '2006-11-15 14:57:09.000000', NULL, 0),
(3034732, 424336, 14476, '<td valign="top">Beautifully done.  Poetic.</td>', 'Beautifully done.  Poetic.', '2006-11-15 14:59:03.000000', NULL, 0),
(3034767, 424407, 42013, '<td valign="top">Dave,<br/>Great shot. Gave the Fstops quite a scare ;)</td>', 'Dave,Great shot. Gave the Fstops quite a scare ;)', '2006-11-15 15:13:13.000000', NULL, 0),
(3034770, 424112, 45475, '<td valign="top">Hanae, this is a nice shot. Keep up the good work and don''t worry about this score. You are a great photographer!</td>', 'Hanae, this is a nice shot. Keep up the good work and don''t worry about this score. You are a great photographer!', '2006-11-15 15:13:55.000000', NULL, 0),
(3034833, 424378, 45475, '<td valign="top">Quite liked this one. Crisp, clear and colourful. And, you certainly fooled me. Mind you, I even looked at this twice and STILL didn''t pick up the laces til now... :D</td>', 'Quite liked this one. Crisp, clear and colourful. And, you certainly fooled me. Mind you, I even looked at this twice and STILL didn''t pick up the laces til now... :D', '2006-11-15 15:26:52.000000', NULL, 0),
(3034841, 424353, 29486, '<td valign="top">Nice job Erin!</td>', 'Nice job Erin!', '2006-11-15 15:29:34.000000', NULL, 0),
(3034842, 424173, 36060, '<td valign="top">Congrats on your 4th place with this beautiful shot!</td>', 'Congrats on your 4th place with this beautiful shot!', '2006-11-15 15:29:39.000000', NULL, 0),
(3034847, 424101, 36060, '<td valign="top">Congrats on your 5th place with this beautiful shot!</td>', 'Congrats on your 5th place with this beautiful shot!', '2006-11-15 15:30:21.000000', NULL, 0),
(3034853, 424210, 29486, '<td valign="top">Nice photo Steve. You done beat me again.</td>', 'Nice photo Steve. You done beat me again.', '2006-11-15 15:30:56.000000', NULL, 0),
(3034873, 424442, 66267, '<td valign="top">Whaat? No ribbon?! <br/> <br/>This is one of the few picture that doesnt use water as a refective surface!</td>', 'Whaat? No ribbon?!  This is one of the few picture that doesnt use water as a refective surface!', '2006-11-15 15:35:30.000000', NULL, 0),
(3034875, 424358, 45475, '<td valign="top">Ahhh... I see. I think the lack of focus on the branches let you down here. Otherwise, I thought this to be a great composition and the reflection beautiful. You were definitely on the right track :)</td>', 'Ahhh... I see. I think the lack of focus on the branches let you down here. Otherwise, I thought this to be a great composition and the reflection beautiful. You were definitely on the right track :)', '2006-11-15 15:35:35.000000', NULL, 0),
(3034895, 423993, 29906, '<td valign="top">I just don''t get how 3 people gave this a 2, this should have ribboned in my opinion, wonderful shot.</td>', 'I just don''t get how 3 people gave this a 2, this should have ribboned in my opinion, wonderful shot.', '2006-11-15 15:41:08.000000', NULL, 0),
(3034906, 423258, 45475, '<td valign="top">First thing that strikes me here, is the wonderful symmetry between bridge and reflection. Then, the inclusion of the fisherman/boy, gives the eyes a place to stop for a while and contemplate... Lovely b&amp;w. Ever considered taking a boat out on the river and maybe getting a shot of just the bridge and reflection?</td>', 'First thing that strikes me here, is the wonderful symmetry between bridge and reflection. Then, the inclusion of the fisherman/boy, gives the eyes a place to stop for a while and contemplate... Lovely b&w. Ever considered taking a boat out on the river and maybe getting a shot of just the bridge and reflection?', '2006-11-15 15:45:40.000000', NULL, 0),
(3034943, 423232, 15711, '<td valign="top">Amazing work.  Just a stunning vista and excecution of it''s display.</td>', 'Amazing work.  Just a stunning vista and excecution of it''s display.', '2006-11-15 16:00:46.000000', NULL, 0),
(3035012, 423232, 42013, '<td valign="top">Love this shot, especially the contrast between blue and orange. Congrats on the red.</td>', 'Love this shot, especially the contrast between blue and orange. Congrats on the red.', '2006-11-15 16:19:22.000000', NULL, 0),
(3035109, 421391, 66267, '<td valign="top">Ohhhhhh, neat effect</td>', 'Ohhhhhh, neat effect', '2006-11-15 16:36:48.000000', NULL, 0),
(3035440, 424433, 48890, '<td valign="top">This is a pretty shot, a very unusual portrait.  I didn''t vote on it. One displeasing thing about this shot is the presence of weird blotches of colour/noise; you can see them clearly in the hair, in the left shoulder, and the top left corner.  Also, a little distracting detail - the white vertical piece of (I assume) window frame behind you is overlapping.  Since I can''t see how it adds to the shot (it''s not like it adds any context - without the commentary I would not know that this is a window frame), the shot would be better without it, I think.</td>', 'This is a pretty shot, a very unusual portrait.  I didn''t vote on it. One displeasing thing about this shot is the presence of weird blotches of colour/noise; you can see them clearly in the hair, in the left shoulder, and the top left corner.  Also, a little distracting detail - the white vertical piece of (I assume) window frame behind you is overlapping.  Since I can''t see how it adds to the shot (it''s not like it adds any context - without the commentary I would not know that this is a window frame), the shot would be better without it, I think.', '2006-11-15 18:38:28.000000', NULL, 0),
(3035492, 423188, 37909, '<td valign="top">Thanks to everyone for their votes and comments! They are really appreciated.  BTW, shannylee13, you called it! :)</td>', 'Thanks to everyone for their votes and comments! They are really appreciated.  BTW, shannylee13, you called it! :)', '2006-11-15 18:55:22.000000', NULL, 0),
(3035586, 424112, 55838, '<td valign="top">I like that you tried something different Hanae and the leaves form sort of a cool frame for the shot.  Unfortunately the pic just feels a little dull - nothing jumps out and grabs the viewer.</td>', 'I like that you tried something different Hanae and the leaves form sort of a cool frame for the shot.  Unfortunately the pic just feels a little dull - nothing jumps out and grabs the viewer.', '2006-11-15 19:50:26.000000', NULL, 0),
(3035597, 424407, 49963, '<td valign="top">Amazing light! Well done :)</td>', 'Amazing light! Well done :)', '2006-11-15 19:53:52.000000', NULL, 0),
(3035612, 424358, 55838, '<td valign="top">I agree that the composition holds some interest here and I see why you went for it - something a little different.  Cool tree roots with a perfect reflection - very organic shapes and the little splash of green leaves is nice.  A little more contrast and saturation of the green maybe and I agree with you about the need for better focus overall.  Don''t beat yourself up sister!  Hey...you got 11 votes of seven or better!  :)</td>', 'I agree that the composition holds some interest here and I see why you went for it - something a little different.  Cool tree roots with a perfect reflection - very organic shapes and the little splash of green leaves is nice.  A little more contrast and saturation of the green maybe and I agree with you about the need for better focus overall.  Don''t beat yourself up sister!  Hey...you got 11 votes of seven or better!  :)', '2006-11-15 19:57:34.000000', NULL, 0),
(3035630, 424378, 55838, '<td valign="top">Ha!  Very good idea to set up the "reflection" like this.  Cool &amp; creative!</td>', 'Ha!  Very good idea to set up the "reflection" like this.  Cool & creative!', '2006-11-15 20:02:27.000000', NULL, 0),
