(3140534, 424433, 37961, '<td valign="top">I like this.</td>', 'I like this.', '2006-12-21 22:19:45.000000', NULL, 0),
(3158309, 423938, 50641, '<td valign="top">This is a fantastic abstract.  I can''t quite make myself see the sculpture, but what I do see are 2 halves of a banana surrounding the face of an alien penguin who is holding a tube up to his nose.  Through the tube we see other penguins on the icy water.  Fantastic!</td>', 'This is a fantastic abstract.  I can''t quite make myself see the sculpture, but what I do see are 2 halves of a banana surrounding the face of an alien penguin who is holding a tube up to his nose.  Through the tube we see other penguins on the icy water.  Fantastic!', '2006-12-29 01:38:56.000000', NULL, 0),
(3161669, 422090, 45631, '<td valign="top">Love this shot.</td>', 'Love this shot.', '2006-12-30 03:50:24.000000', NULL, 0),
