INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3225976, 424325, 6870, '<td valign="top">This is an artsy and gutsy shot. The low scores puzzle me, even for DPC voters.</td>', 'This is an artsy and gutsy shot. The low scores puzzle me, even for DPC voters.', '2007-01-13 13:52:07.000000', NULL, 0),
(3271020, 423938, 62318, '<td valign="top">Another terrific picture. You eye moves through the entire frame both on the inside and the outside. It is a beauty and the light and people add a very interesting depth. I''m surprised this one did so poorly, I''m guessing people thought it was some sort of mirror.</td>', 'Another terrific picture. You eye moves through the entire frame both on the inside and the outside. It is a beauty and the light and people add a very interesting depth. I''m surprised this one did so poorly, I''m guessing people thought it was some sort of mirror.', '2007-01-23 13:55:54.000000', NULL, 0),
(3315756, 422545, 24454, '<td valign="top">How strange!  No comments and a 4.6 score???   I don''t get it.   I think this is a lovely shot!!   Certainly undeserving of a 4.6.<br/> <br/>I love those blues, and the dreamy processing is beautiful.   Too bad it wasn''t advanced editing so you could lighten up and show a little more detail in the foreground.  But still.  I really like the photo alot!<br/> <br/></td>', 'How strange!  No comments and a 4.6 score???   I don''t get it.   I think this is a lovely shot!!   Certainly undeserving of a 4.6. I love those blues, and the dreamy processing is beautiful.   Too bad it wasn''t advanced editing so you could lighten up and show a little more detail in the foreground.  But still.  I really like the photo alot! ', '2007-02-01 21:31:53.000000', NULL, 0),
(3337483, 423993, 48227, '<td valign="top">Underrated!!! Excellent photo.</td>', 'Underrated!!! Excellent photo.', '2007-02-07 00:34:14.000000', NULL, 0),
(3376008, 423257, 15567, '<td valign="top">this is beautiful. I can see why you like photographing it.<br/>You picked the perfect time with the Autumn backlighting :)<br/>Now I know I have never seen this mill before in my travels</td>', 'this is beautiful. I can see why you like photographing it.You picked the perfect time with the Autumn backlighting :)Now I know I have never seen this mill before in my travels', '2007-02-17 18:18:40.000000', NULL, 0),
(3420983, 424313, 65319, '<td valign="top">I''ve been to the Ventura Pier and it never looked as good as this.  What an absolutely stunning photo!  I wish I had this one in my own collection!</td>', 'I''ve been to the Ventura Pier and it never looked as good as this.  What an absolutely stunning photo!  I wish I had this one in my own collection!', '2007-03-01 22:11:09.000000', NULL, 0),
(3423953, 423806, 54033, '<td valign="top">I do not care either. This is a 10+ shoot.<br/>Great, really good. never seen this phot before.<br/>Man I love it.</td>', 'I do not care either. This is a 10+ shoot.Great, really good. never seen this phot before.Man I love it.', '2007-03-02 18:54:54.000000', NULL, 0),
